## C — COMPONENTES

### [C01] Botón · [C02] Card · [C03] Separador
```css
.nc-btn{position:relative;padding:1rem 3.2rem;font:300 .7rem/1 var(--nc-font);
  letter-spacing:.45em;text-transform:uppercase;color:var(--nc-white-200);
  background:transparent;border:1px solid var(--nc-line-strong);cursor:pointer;
  transition:border-color var(--nc-slow) var(--nc-ease),
    box-shadow var(--nc-slow) var(--nc-ease),background var(--nc-slow) var(--nc-ease)}
.nc-btn:hover{border-color:rgba(232,240,255,.4);background:rgba(232,240,255,.03);
  box-shadow:0 0 32px rgba(232,240,255,.06),inset 0 0 18px rgba(232,240,255,.04)}

.nc-card{background:linear-gradient(180deg,rgba(10,22,40,.55),rgba(0,0,0,.6));
  border:1px solid var(--nc-line);padding:3rem 2.5rem;
  transition:border-color var(--nc-slow) var(--nc-ease),transform var(--nc-slow) var(--nc-ease)}
.nc-card:hover{border-color:var(--nc-line-strong);transform:translateY(-2px)}

.nc-hr{border:0;height:1px;width:min(60%,480px);margin:6rem auto;
  background:linear-gradient(90deg,transparent,var(--nc-line-strong),transparent)}
```

### [C04] Cursor con rastro frío
```js
(function(){
  if(matchMedia('(pointer:coarse)').matches)return;
  const dot=document.createElement('div');dot.className='nc-cursor';
  const trail=document.createElement('div');trail.className='nc-trail';
  document.body.append(trail,dot);
  let tx=0,ty=0,x=0,y=0;
  addEventListener('mousemove',e=>{tx=e.clientX;ty=e.clientY;
    dot.style.transform=`translate(${tx}px,${ty}px)`});
  (function loop(){x+=(tx-x)*.08;y+=(ty-y)*.08;
    trail.style.transform=`translate(${x}px,${y}px)`;requestAnimationFrame(loop)})();
})();
```
```css
@media(pointer:fine){
  body{cursor:none}
  .nc-cursor{position:fixed;left:-2px;top:-2px;width:4px;height:4px;border-radius:50%;
    background:#E8F0FF;z-index:99;pointer-events:none;box-shadow:0 0 8px rgba(232,240,255,.8)}
  .nc-trail{position:fixed;left:-14px;top:-14px;width:28px;height:28px;border-radius:50%;
    border:1px solid rgba(232,240,255,.15);z-index:98;pointer-events:none}
}
```

### [C05] Inputs · [C06] Nav · [C07] Loader
```css
.nc-input{width:100%;background:rgba(10,22,40,.35);border:0;
  border-bottom:1px solid var(--nc-line-strong);color:var(--nc-white-100);
  padding:1rem .25rem;font:300 1rem var(--nc-font);letter-spacing:.04em;
  transition:border-color var(--nc-slow) var(--nc-ease),box-shadow var(--nc-slow) var(--nc-ease)}
.nc-input:focus{outline:none;border-bottom-color:rgba(232,240,255,.45);
  box-shadow:0 8px 24px -18px rgba(232,240,255,.35)}
.nc-input::placeholder{color:rgba(232,240,255,.25)}

.nc-nav{position:fixed;inset:0 0 auto;z-index:40;display:flex;
  justify-content:space-between;align-items:center;padding:1.6rem 3rem;
  background:rgba(0,0,0,.35);backdrop-filter:blur(14px);border-bottom:1px solid var(--nc-line)}
.nc-logo{font-weight:300;letter-spacing:.5em;font-size:.8rem;color:var(--nc-white-100)}

.nc-loader{width:44px;height:44px;border-radius:50%;
  border:1px solid rgba(232,240,255,.08);border-top-color:rgba(232,240,255,.5);
  animation:ncSpin 2.4s linear infinite}
@keyframes ncSpin{to{transform:rotate(360deg)}}
```

---

## D — MOVIMIENTO

### [D01] Reveal ceremonial · [D02] Disciplina de movimiento
```js
const io=new IntersectionObserver(es=>{
  es.forEach(e=>e.isIntersecting&&e.target.classList.add('nc-in'));
},{threshold:.15});
document.querySelectorAll('.nc-reveal').forEach(el=>io.observe(el));
```
```css
.nc-reveal{opacity:0;transform:translateY(18px);filter:blur(6px);
  transition:opacity var(--nc-slower) var(--nc-ease),
    transform var(--nc-slower) var(--nc-ease),filter var(--nc-slower) var(--nc-ease)}
.nc-in{opacity:1;transform:none;filter:none}
@media(prefers-reduced-motion:reduce){
  *,*::before,*::after{animation:none!important;transition:none!important}
  html{scroll-behavior:auto}
}
```

---

## AV — ASSETS VISUALES GENERADOS (ya entregados arriba)

Guárdalos en `/assets/` y úsalos así:

| ID | Contenido | Uso recomendado |
|---|---|---|
| AV-01 | Anillos concéntricos + haz vertical sobre vacío azul profundo | Hero / portada |
| AV-02 | Figura solitaria de espaldas sobre agua negra reflectante, haz cenital | Sección manifiesto / propósito |
| AV-03 | Campo de niebla etérea con líneas de luz verticales | Fondos de secciones intermedias |

```css
.nc-hero{background:#000 url("/assets/av-01.jpg") center/cover no-repeat}
.nc-hero::after{content:"";position:absolute;inset:0;
  background:radial-gradient(120% 90% at 50% 50%,transparent 55%,rgba(0,0,0,.75))}
```

---

## E — ALGORITMO DE GENERACIÓN INFINITA DE ASSETS/SHADERS SIN API

**Principio:** seed → hash → PRNG determinista → parámetros constreñidos a la paleta NOIACORE → render local (SVG / GLSL / Canvas) → cache. Cero red, cero claves, infinito y reproducible. La marca **no puede romperse** porque la paleta y los rangos están sellados en el spec.

### [E01+E02] Seed + PRNG (xmur3 / mulberry32)
```js
function ncHash(str){let h=1779033703^str.length;
  for(let i=0;i<str.length;i++){h=Math.imul(h^str.charCodeAt(i),3432918353);h=h<<13|h>>>19}
  return()=>{h=Math.imul(h^h>>>16,2246822507);h=Math.imul(h^h>>>13,3266489909);return(h^=h>>>16)>>>0}}
function ncRng(seed){let a=ncHash(String(seed))();
  return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);
    t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
```

### [E03] Spec constreñido (la piel cambia, la identidad no)
```js
function ncSpec(seed){
  const R=ncRng(seed),blues=['#0A1628','#0F1C2E','#15233A','#1A2A40'];
  return{seed:String(seed),
    ringCount:3+Math.floor(R()*5),        // 3–7 anillos
    ringGap:60+R()*80,
    beamX:.5+(R()-.5)*.12,                // simetría casi perfecta
    beamOpacity:.06+R()*.16,
    particles:Math.floor(12+R()*40),
    etherTop:blues[Math.floor(R()*4)],
    etherBottom:blues[Math.floor(R()*4)],
    glow:.03+R()*.05, drift:8+R()*14};
}
```

### [E04] SVG infinito → data-URI (fondo CSS instantáneo)
```js
function ncSvgAsset(seed){
  const s=ncSpec(seed),S=1200,c=S/2;let rings='',dots='';
  for(let i=1;i<=s.ringCount;i++)
    rings+=`<circle cx="${c}" cy="${c}" r="${i*s.ringGap}" fill="none" stroke="#E8F0FF" stroke-opacity="${(.12/i).toFixed(3)}"/>`;
  const R=ncRng(seed+':pts');
  for(let i=0;i<s.particles;i++)
    dots+=`<circle cx="${(R()*S)|0}" cy="${(R()*S)|0}" r="${(R()*1.2+.2).toFixed(2)}" fill="#E8F0FF" fill-opacity="${(R()*.3+.05).toFixed(2)}"/>`;
  const bx=(S*s.beamX)|0;
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${S}" height="${S}">
<defs><radialGradient id="g" cx="50%" cy="42%" r="75%">
<stop offset="0%" stop-color="${s.etherTop}"/><stop offset="100%" stop-color="#000000"/></radialGradient></defs>
<rect width="${S}" height="${S}" fill="#000"/>
<rect width="${S}" height="${S}" fill="url(#g)" opacity=".55"/>
<line x1="${bx}" y1="0" x2="${bx}" y2="${S}" stroke="#E8F0FF" stroke-opacity="${s.beamOpacity}"/>
${rings}${dots}</svg>`;
  return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
}
```

### [E05] Shader GLSL infinito (compila en el navegador, usa `ncShader` de B09)
```js
function hexToRgb(h){const n=parseInt(h.slice(1),16);
  return `${((n>>16&255)/255).toFixed(3)},${((n>>8&255)/255).toFixed(3)},${((n&255)/255).toFixed(3)}`}
function ncShaderAsset(seed){
  const s=ncSpec(seed);
  return `precision highp float;uniform float t;uniform vec2 r;
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);
 return mix(mix(hash(i),hash(i+vec2(1.,0.)),f.x),
            mix(hash(i+vec2(0.,1.)),hash(i+vec2(1.,1.)),f.x),f.y);}
void main(){
 vec2 uv=(gl_FragCoord.xy-.5*r)/r.y;float d=length(uv);
 vec3 col=mix(vec3(0.),vec3(${hexToRgb(s.etherTop)}),noise(uv*2.+t*.02)*.5);
 float ring=sin(d*${(18+s.ringCount*4).toFixed(1)}-t*.2)*.5+.5;
 col+=vec3(.91,.94,1.)*smoothstep(.98,1.,ring)*${s.glow.toFixed(3)}*smoothstep(.8,.1,d);
 col+=vec3(.91,.94,1.)*smoothstep(.003,.0,abs(uv.x-${(s.beamX-.5).toFixed(3)}))*${s.beamOpacity.toFixed(3)}*(1.-abs(uv.y));
 col*=smoothstep(1.2,.3,d);
 gl_FragColor=vec4(col,1.);
}`;
}
```

### [E06] Textura canvas → PNG
```js
function ncTexture(seed,size=1024){
  const R=ncRng(seed),cv=document.createElement('canvas');
  cv.width=cv.height=size;const x=cv.getContext('2d');
  x.fillStyle='#000';x.fillRect(0,0,size,size);
  const s=ncSpec(seed);
  const g=x.createRadialGradient(size/2,size*.42,0,size/2,size*.42,size*.75);
  g.addColorStop(0,s.etherTop+'88');g.addColorStop(1,'#000000');
  x.fillStyle=g;x.fillRect(0,0,size,size);
  for(let i=0;i<s.particles*8;i++){
    x.fillStyle=`rgba(232,240,255,${(R()*.25+.03).toFixed(2)})`;
    x.beginPath();x.arc(R()*size,R()*size,R()*1.3+.2,0,7);x.fill();
  }
  return cv.toDataURL('image/png');
}
```

### [E07] Cache determinista + pipeline infinito + aplicación
```js
const ncCache={key:s=>'nc:asset:'+s,
  get(s){return localStorage.getItem(this.key(s))},
  set(s,v){try{localStorage.setItem(this.key(s),v)}catch(e){}}};
function ncAsset(seed){let u=ncCache.get(seed);
  if(!u){u=ncSvgAsset(seed);ncCache.set(seed,u)}return u}
function ncApply(seed,el=document.body){
  const s=ncSpec(seed);
  el.style.setProperty('--nc-drift',s.drift+'s');
  el.style.setProperty('--nc-glow',s.glow);
  el.style.backgroundImage=`url("${ncAsset(seed)}")`;
}
/* Bucle infinito: cada seed → asset único y reproducible */
let ix=1; const nextAsset=()=>ncApply('NOIACORE-'+String(ix++).padStart(4,'0'));
```

