```js
function ncShader(canvas,frag){
  const gl=canvas.getContext('webgl');
  const vs='attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}';
  const sh=(t,s)=>{const o=gl.createShader(t);gl.shaderSource(o,s);gl.compileShader(o);return o};
  const pr=gl.createProgram();
  gl.attachShader(pr,sh(gl.VERTEX_SHADER,vs));
  gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,frag));
  gl.linkProgram(pr);gl.useProgram(pr);
  const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);
  gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);
  const loc=gl.getAttribLocation(pr,'p');
  gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);
  const uT=gl.getUniformLocation(pr,'t'),uR=gl.getUniformLocation(pr,'r');
  (function loop(now){
    const w=canvas.clientWidth,h=canvas.clientHeight;
    if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}
    gl.viewport(0,0,w,h);gl.uniform1f(uT,now*.001);gl.uniform2f(uR,w,h);
    gl.drawArrays(gl.TRIANGLES,0,3);requestAnimationFrame(loop);
  })(0);
}
const NOIACORE_FRAG=`
precision highp float;uniform float t;uniform vec2 r;
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);
 return mix(mix(hash(i),hash(i+vec2(1.,0.)),f.x),
            mix(hash(i+vec2(0.,1.)),hash(i+vec2(1.,1.)),f.x),f.y);}
void main(){
 vec2 uv=(gl_FragCoord.xy-.5*r)/r.y;float d=length(uv);
 vec3 col=mix(vec3(.008,.016,.032),vec3(.059,.086,.142),noise(uv*2.+t*.02)*.6);
 float ring=sin(d*28.-t*.25)*.5+.5;
 col+=vec3(.91,.94,1.)*smoothstep(.985,1.,ring)*.05*smoothstep(.75,.1,d);
 col+=vec3(.91,.94,1.)*smoothstep(.0025,.0,abs(uv.x))*.6*(1.-abs(uv.y));
 col*=smoothstep(1.15,.35,d);
 gl_FragColor=vec4(col,1.);
}`;
ncShader(document.querySelector('#nc-bg'),NOIACORE_FRAG);
